use serde_json::{json,Value};use sha2::{Sha256,Digest};use std::{fs,path::Path,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/swiss-control-audit175";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let ids:Value=serde_json::from_slice(&fs::read("/home/ubuntu/src/zopro-perf-work/swiss-groups-sdk175/identities.json").unwrap()).unwrap();let mut rows=vec![];for v in["accepted","OFF"]{let input=ids[v]["binary"].as_str().unwrap();let before=hash(input);assert_eq!(before,ids[v]["sha256"]);let section=format!("{R}/{v}-safe-text.bin");let output=format!("{R}/{v}-safe-objcopy-output.elf");assert!(!Path::new(&output).exists());assert!(Command::new("objcopy").arg(format!("--dump-section=.text={section}")).arg(input).arg(&output).status().unwrap().success());assert_eq!(hash(input),before);assert_eq!(hash(&section),hash(format!("{R}/{v}-text.bin")));rows.push(json!({"variant":v,"input_sha256_before_after":before,"explicit_throwaway_output":output,"input_unchanged":true,"text_section_matches_first_dump":true,"text_sha256":hash(section)}));}fs::write(format!("{R}/safe-objcopy.json"),serde_json::to_vec_pretty(&json!({"safe_crosscheck":rows,"no_new_capture_or_test":true})).unwrap()).unwrap();println!("Both exact SDK hashes retained; explicit-output objcopy dump matches original text sections");}
